c.java:
class Solution {
    public List<Integer> stableMountains(int[] height, int threshold) {
        return java.util.stream.IntStream.range(1, height.length)
            .filter(i -> height[i - 1] > threshold)
            .boxed().collect(java.util.stream.Collectors.toList());
    }
}

